CREATE TABLE IF NOT EXISTS rl."bs_gs_canal" (
  "id_fila" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "fila" integer NOT NULL,
  "id" double precision,
  "codigo" extensions.citext,
  "fecha" timestamp,
  "empresa" extensions.citext,
  "fundo" extensions.citext,
  "sede" extensions.citext,
  "categoria" extensions.citext,
  "mensaje" extensions.citext,
  "contacto" extensions.citext,
  "origen" extensions.citext,
  "huella" extensions.citext,
  "estado" extensions.citext,
  "atendido_por" extensions.citext,
  "fecha_atencion" timestamp,
  "respuesta" extensions.citext,
  "derivado_a" extensions.citext,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "updated_by" extensions.citext,
  "updated_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext,
  "actualizado" timestamp DEFAULT (now() at time zone 'utc') NOT NULL,
  PRIMARY KEY ("id_fila")
);
CREATE UNIQUE INDEX IF NOT EXISTS "ix_bs_gs_canal_ux_bs_gs_canal_fila" ON rl."bs_gs_canal" ("fila");
CREATE TABLE IF NOT EXISTS rl."bs_gs_canal__carga" (
