  "sede" extensions.citext,
  "categoria" extensions.citext,
  "mensaje" extensions.citext,
  "contacto" extensions.citext,
  "origen" extensions.citext,
  "huella" extensions.citext,
  "estado" extensions.citext,
  "atendido_por" extensions.citext,
  "fecha_atencion" timestamp,
  "respuesta" extensions.citext,
  "derivado_a" extensions.citext,
  "created_by" extensions.citext,
  "created_at" timestamp,
  "updated_by" extensions.citext,
  "updated_at" timestamp,
  "anulado" extensions.citext,
  "otros" extensions.citext
);
